// Builds dist/SleeperAutopilot.gs: Code.gs with Index.html, the manifest and
// release notes (CHANGES.md) embedded, so setup is a single paste into a new
// Apps Script project and later versions can install themselves.
//   node dev/bundle.js          write the file
//   node dev/bundle.js --check  exit 1 if the committed file is stale
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const dir = path.join(__dirname, '..');
const read = (f) => fs.readFileSync(path.join(dir, f), 'utf8');
const out = path.join(dir, 'dist', 'SleeperAutopilot.gs');

function releaseNotes() {
  return read('CHANGES.md').split(/^## /m).slice(1).map((block) => {
    const [title, ...rest] = block.trim().split('\n');
    return { title: title.trim(), items: rest.map((l) => l.replace(/^-\s*/, '').trim()).filter(Boolean) };
  });
}

function build() {
  const code = read('Code.gs'), html = read('Index.html'), manifest = read('appsscript.json');
  const notes = releaseNotes();
  const info = {
    id: crypto.createHash('sha256').update(code + html + manifest).digest('hex').slice(0, 10),
    version: notes.length,
    title: notes[0].title,
    notes: notes.slice(0, 8),
  };
  return '// GENERATED by dev/bundle.js from Code.gs + Index.html. Paste this whole file into\n' +
    '// a new Apps Script project (https://script.new). Source: fantasy/apps-script/ in the repo.\n\n' +
    code +
    '\nvar UI_HTML = ' + JSON.stringify(html) + ';\n' +
    'var MANIFEST_JSON = ' + JSON.stringify(manifest) + ';\n' +
    'var BUILD_INFO = ' + JSON.stringify(info) + ';\n';
}

if (process.argv.includes('--check')) {
  const stale = !fs.existsSync(out) || fs.readFileSync(out, 'utf8') !== build();
  if (stale) { console.error('dist/SleeperAutopilot.gs is stale: run node dev/bundle.js'); process.exit(1); }
} else {
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, build());
  console.log('wrote', path.relative(process.cwd(), out));
}
